{
  "name": "@sanoma-ai/connector-opencode",
  "version": "0.11.24",
  "description": "OpenCode, the open-source coding agent, for Sanoma's chat on a person's own plan",
  "keywords": [
    "coding-agent",
    "connector",
    "opencode",
    "sanoma",
    "sanoma-connector"
  ],
  "homepage": "https://github.com/Sanoma-AI/sanoma/tree/main/connectors/opencode#readme",
  "bugs": "https://github.com/Sanoma-AI/sanoma/issues",
  "license": "FSL-1.1-ALv2",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Sanoma-AI/sanoma.git",
    "directory": "connectors/opencode"
  },
  "files": [
    "dist",
    "logo.svg",
    "logo-dark.svg",
    "README.md",
    "LICENSE",
    "MARKS-LICENSE"
  ],
  "type": "module",
  "sideEffects": false,
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "publishConfig": {
    "access": "public"
  },
  "devDependencies": {
    "sanoma": "0.11.24",
    "zod": "^4.6.5"
  },
  "peerDependencies": {
    "sanoma": "0.11.24",
    "zod": "^4"
  },
  "engines": {
    "node": ">=26"
  },
  "sanoma": {
    "title": "OpenCode",
    "logo": "logo.svg",
    "logoDark": "logo-dark.svg",
    "agent": {
      "id": "opencode",
      "title": "OpenCode"
    }
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "clean": "rm -rf dist",
    "watch": "tsc -p tsconfig.build.json --watch --preserveWatchOutput"
  }
}
